<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Snippet\Application\Usecase\Retrieve;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\Snippet\Domain\SnippetRef;
use Civi\Lughauth\Features\Document\Snippet\Application\Service\Visibility\SnippetVisibilityService;
use Civi\Lughauth\Features\Document\Snippet\Domain\Gateway\SnippetReadGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class SnippetRetrieveUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly SnippetVisibilityService $visibility,
        private readonly SnippetReadGateway $reader
    ) {
    }

    public function allowRetrieve(?SnippetRef $ref = null): Allow
    {
        $this->logDebug("Check allow of retrieve usecase for Snippet");
        $span = $this->startSpan("Check allow of retrieve usecase for Snippet");
        try {
            $result = $this->dispatcher->dispatch(new SnippetRetrieveAllowDecision(Allow::allowed('retrieve', 'Allowed to retrieve by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function hiddenFields(?SnippetRef $ref = null): array
    {
        $this->logDebug("Check hidden fields usecase for Snippet");
        $span = $this->startSpan("Check hidden fields usecase for Snippet");
        try {
            return $this->visibility->fieldsToHide($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieve(string $uid): SnippetRetrieveResult
    {
        $this->logDebug("Run retrieve usecase for Snippet");
        $span = $this->startSpan("Run retrieve usecase for Snippet");
        try {
            $ref = new SnippetRef($uid);
            $allow = $this->allowRetrieve($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to retrieve Snippet');
            }
            if (!$result = $this->visibility->retrieveVisible($ref)) {
                throw new NotFoundException($uid);
            }
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new SnippetRetrieveResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
